using ABB.Robotics.Math;using ABB.Robotics.RobotStudio;using ABB.Robotics.RobotStudio.Stations;
namespace ModelReview014 {
 public sealed class NoMotionSnapshot014 {
  readonly string stationPath;readonly string actorName;readonly Guid systemId,robotId,configurationId,sourceId;
  readonly Station station;readonly Mechanism robot;readonly SmartComponent actor;readonly int thread;
  readonly GraphicComponent[] objects;readonly Dictionary<GraphicComponent,double[]> world;readonly double[] joints;readonly byte[] structuralBytes;
  public string Digest=>Convert.ToHexString(SHA256.HashData(structuralBytes));
  public double[] ModelJointsRad=>(double[])joints.Clone();public Guid RobotId=>Guid.Parse(robot.UniqueId);public Guid SourceId=>Guid.Parse(station.GraphicComponents.OfType<Part>().Single(p=>p.Name=="SourcePart").UniqueId);public Guid ConfigurationId=>Guid.Parse(Simulator.ActiveConfiguration.UniqueId);
  static void Require(bool ok,string text){if(!ok)throw new InvalidOperationException(text);}
  static bool False(object runtime,string name){var p=runtime.GetType().GetProperty(name,System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance);return p!=null&&p.PropertyType==typeof(bool)&&p.GetIndexParameters().Length==0&&p.GetMethod!=null&&p.GetMethod.IsPublic&&!(bool)p.GetValue(runtime);}
  static string N(double v){Require(double.IsFinite(v),"Finite native value required");return v.ToString("R",CultureInfo.InvariantCulture);}
  static double[] Elements(Matrix4 value)=>value.Elements.ToArray();
  static bool Identity(Matrix4 value)=>value.Elements.Zip(Matrix4.Identity.Elements,(a,b)=>System.Math.Abs(a-b)).Max()<=1e-10;
  void BaseFacts(){
   Require(Environment.CurrentManagedThreadId==thread&&Object.ReferenceEquals(Station.ActiveStation,station)&&Object.ReferenceEquals(Project.ActiveProject,station)&&station.FileInfo?.FullName==stationPath,"Exact UI-owned actual runtime required");var vc=station.VirtualControllers.Single();Require(Guid.Parse(vc.SystemId)==systemId&&vc.SystemState.ToString()=="Started"&&vc.MappingState.ToString()=="Mapped"&&vc.MechanicalUnits.Count(u=>Object.ReferenceEquals(u.Mechanism,robot))==1&&Identity(robot.Transform.GlobalMatrix)&&Identity(robot.ModelBaseFrame),"Mapped owned robot and identity world base required");
   Require(Guid.Parse(Simulator.ActiveConfiguration.UniqueId)==configurationId&&Simulator.State==SimulationState.Stopped&&Simulator.CurrentTime==0&&!Simulator.ActiveConfiguration.ControllerConfigurations[vc].AutoStartProgram&&station.CollisionSets.Count==0&&station.GraphicComponents.Count==32&&station.GraphicComponents.OfType<Part>().Count()==30&&station.GraphicComponents.OfType<SmartComponent>().Count()==1,"Stopped0 unmodified cell before production monitor required");Require(actor.Name==actorName&&actor.CodeBehindStatus==CodeBehindStatus.Loaded&&actor.CodeBehindLocation=="MA6212.Model014.Actor.CellCodeBehind,MA6212_Model014_ActorVisionSixM3.dll"&&actor.StateCache.TryGetValue("Model014.Runtime",out object rt)&&rt!=null&&rt.GetType().FullName=="MA6212.Model014.Actor.CellRuntime"&&rt.GetType().Assembly.GetName().Name=="MA6212_Model014_ActorVisionSixM3"&&False(rt,"Armed")&&False(rt,"Faulted")&&!actor.StateCache.ContainsKey("Model014.MonitorOwner"),"Exact live unarmed and healthy actor without monitor required");
   var source=station.GraphicComponents.OfType<Part>().Single(p=>p.Name=="SourcePart");var inlet=new Matrix4(new Vector3(.6,-.65,.35));Require(Guid.Parse(source.UniqueId)==sourceId&&System.Math.Abs(source.Transform.GlobalMatrix.Translation.x-inlet.Translation.x)<=.005000001&&System.Math.Abs(source.Transform.GlobalMatrix.Translation.y-inlet.Translation.y)<=.005000001&&System.Math.Abs(source.Transform.GlobalMatrix.Translation.z-inlet.Translation.z)<=1e-10&&source.Transform.GlobalMatrix.Elements.Take(12).Zip(inlet.Elements.Take(12),(a,b)=>System.Math.Abs(a-b)).Max()<=1e-10&&!station.Attachments.Any(a=>Object.ReferenceEquals(a.AttachmentChild,source)),"Same actual unattached source must remain at inlet");
   var tool=station.GraphicComponents.OfType<Part>().Single(p=>p.Name=="VacuumTool");var mount=station.Attachments.Where(a=>Object.ReferenceEquals(a.AttachmentChild,tool)).ToArray();Require(mount.Length==1&&Object.ReferenceEquals(mount[0].AttachmentParent,robot.GraphicComponents.Single(g=>g.Name=="Link6")),"Exact physical owned flange mount required");var tcp=tool.Transform.GlobalMatrix*new Matrix4(new Vector3(0,0,.15));var ready=new Matrix4(new Vector3(.55,0,.75),new Quaternion(new double[]{0,1,0,0}));Require((tcp.Translation-ready.Translation).Length()<=.00001&&new[]{0,1,2,4,5,6,8,9,10}.Max(i=>System.Math.Abs(tcp.Elements[i]-ready.Elements[i]))<=1e-5,"Actual tool must remain at executed empty Ready");
  }
  byte[] Structure(){var b=new StringBuilder();b.Append("configuration=").Append(Simulator.ActiveConfiguration.UniqueId).Append(";clock=").Append(N(Simulator.CurrentTime)).Append(";sim=").Append(Simulator.State).Append(';');foreach(var o in station.GraphicComponents.OrderBy(o=>Guid.Parse(o.UniqueId))){b.Append(Guid.Parse(o.UniqueId).ToString("D")).Append('|').Append(o.Name).Append('|').Append(o.GetType().FullName).Append('|');foreach(double v in o.Transform.GlobalMatrix.Elements)b.Append(N(v)).Append(';');}b.Append("q=");foreach(double v in robot.GetJointValues())b.Append(N(v)).Append(';');foreach(var a in station.Attachments.OrderBy(a=>Guid.Parse(a.AttachmentChild.UniqueId)))b.Append("attachment=").Append(Guid.Parse(a.AttachmentChild.UniqueId)).Append('>').Append(a.AttachmentParent.UniqueId).Append('|').Append(a.AttachmentParent.Name).Append(';');return Encoding.UTF8.GetBytes(b.ToString());}
  public NoMotionSnapshot014(string actualStationPath,Guid actualSystemId,Guid actualRobotId,Guid actualConfigId,Guid actualSourceId){sourceId=actualSourceId;stationPath=actualStationPath;systemId=actualSystemId;robotId=actualRobotId;configurationId=actualConfigId;thread=Environment.CurrentManagedThreadId;station=Station.ActiveStation??throw new InvalidOperationException("No actual station");robot=station.GraphicComponents.OfType<Mechanism>().Single(m=>Guid.Parse(m.UniqueId)==robotId);actor=station.GraphicComponents.OfType<SmartComponent>().Single();actorName=actor.Name;BaseFacts();objects=station.GraphicComponents.ToArray();world=objects.ToDictionary(o=>o,o=>Elements(o.Transform.GlobalMatrix));joints=(double[])robot.GetJointValues().Clone();structuralBytes=Structure();}
  public string VerifyUnchanged(){BaseFacts();Require(station.GraphicComponents.Count==objects.Length&&objects.All(o=>station.GraphicComponents.Contains(o))&&world.All(p=>p.Key.Transform.GlobalMatrix.Elements.SequenceEqual(p.Value))&&joints.SequenceEqual(robot.GetJointValues())&&Structure().SequenceEqual(structuralBytes),"Calculation changed native identities/world/joints/configuration/clock; retain evidence without repair");return Digest;}
  public XElement Evidence(string name){VerifyUnchanged();return new XElement(name,new XElement("StructuralDigestSHA256",Digest),new XElement("RobotId",RobotId),new XElement("SourceId",SourceId),new XElement("ConfigurationId",ConfigurationId),new XElement("ModelJointsRad",String.Join(",",joints.Select(N))),new XElement("NativeSimulator",Simulator.State),new XElement("NativeTimeRaw",Simulator.CurrentTime),new XElement("ActorArmed",false),new XElement("OriginalObjects",objects.Select(o=>new XElement("Object",new XAttribute("id",Guid.Parse(o.UniqueId)),new XAttribute("name",o.Name),new XElement("WorldMatrix",String.Join(",",world[o].Select(N)))))));}
 }
}
